for fn, arr in sets.items():
    path='/mnt/data/review_edit/data/'+fn
    s=open(path,encoding='utf8').read()
    i=0
    def repl(m):
        nonlocal_i=None
        global i
        opts=arr[i]; i+=1
        # JS double-quoted strings, escape backslash/quotes/newlines
        encoded=json.dumps(opts, ensure_ascii=False)
        return 'options: '+encoded+','
    s2=re.sub(r'options:\s*\[(?:.|\n)*?\],', repl, s, count=len(arr))
    if i != len(arr): raise SystemExit(f'{fn}: replaced {i}/{len(arr)}')
    open(path,'w',encoding='utf8').write(s2)
    print(fn, 'updated', i)
